# --- 같은 비밀번호를 세 번 인코딩 ---

@Test
void encodeThrice() {
    PasswordEncoder encoder =
            PasswordEncoderFactories.createDelegatingPasswordEncoder();
    for (int i = 0; i < 3; i++) {
        String hashed = encoder.encode("1234");
        System.out.println(hashed + "  matches="
                + encoder.matches("1234", hashed));
    }
}

