# --- cost 를 올려 본다 ---

@Test
void cost() {
    for (int cost : new int[]{4, 10, 12, 14}) {
        BCryptPasswordEncoder e = new BCryptPasswordEncoder(cost);
        long t = System.nanoTime();
        e.encode("1234");
        System.out.printf("cost=%2d  %6.1f ms%n", cost,
                (System.nanoTime() - t) / 1_000_000.0);
    }
}

