# --- SHA-256 과 비교 ---

@Test
void fast() {
    long t = System.nanoTime();
    for (int i = 0; i < 100_000; i++) {
        MessageDigest.getInstance("SHA-256").digest("1234".getBytes());
    }
    System.out.println((System.nanoTime() - t) / 1_000_000 + " ms for 100k");
}

